public static boolean iscube(long a) {
    if (a < 0) {
        a = -a; // Make the number positive to find its cube root
    }
    long cubeRoot = (long) Math.round(Math.cbrt(a));
    return !(cubeRoot * cubeRoot * cubeRoot == a);
}

