    // (6l)
    // >>> hexKey(("2020"))
    // (2l)

    public static long hexKey(String num) {
        // Define a set of characters that represent prime hexadecimal digits
        Set<Character> primeHexDigits = new HashSet<>(Arrays.asList('2', '3', '5', '7', 'B', 'D'));

        // Initialize a counter for prime hexadecimal digits
        long primeCount = 0;

        // Iterate over each character in the input string
        for (char c : num.toCharArray()) {
            // Check if the character is a prime hexadecimal digit
            if (primeHexDigits.contains(c)) {
                // Increment the counter if it is
                primeCount++;
            }
        }

        // Return the count of prime hexadecimal digits
        return primeCount;
    }

}

