public class Demo {

    public static List<Pair<Float, Float>> listToFloat(List<Pair<String, String>> testList) {
        List<Pair<Float, Float>> result = new ArrayList<>();

        for (Pair<String, String> pair : testList) {
            try {
                // Attempt to parse the first element as a float
                float firstElement = Float.parseFloat(pair.getValue0());
                // Attempt to parse the second element as a float
                float secondElement = Float.parseFloat(pair.getValue1());
                // Add the parsed values as a Pair to the result list
                result.add(Pair.with(firstElement, secondElement));
            } catch (NumberFormatException e) {
                // If parsing fails, add null to the result list
                result.add(Pair.with(null, null));
            }
        }

        return result;
    }
}

